    /**
     * The transform window of Table 7.33, which the standard prints to five
     * decimals: the Kaiser-Bessel derived window of alpha 5 over 512 points,
     * computed here in full. `gen_tables.py` checks that it rounds to every
     * printed value. Only the rising half is kept; the window is symmetric.
     */
    val WINDOW: FloatArray = run {
        val alpha = 5.0
        val kaiser = DoubleArray(257) { j ->
            val r = 4.0 * j / 512 - 1
            besselI0(PI * alpha * sqrt(1 - r * r))
        }
        val total = kaiser.sum()
        var running = 0.0
        FloatArray(256) { n ->
            running += kaiser[n]
            sqrt(running / total).toFloat()
        }
    }

    /** The modified Bessel function of the first kind and order zero, by its power series. */
    private fun besselI0(x: Double): Double {
        var term = 1.0
        var total = 1.0
        var k = 1
        while (term > 1e-20 * total) {
            val half = x / (2 * k)
            term *= half * half
            total += term
            k++
        }
        return total
    }
